input.content:
import { Metadata } from 'next';

export const metadata: Metadata = {
  title: 'Server Timestamp',
  description: 'Current server timestamp that updates on each request',
};

export default function ServerTimestampPage() {
  // This is a Server Component (default in App Router)
  // The timestamp will be generated fresh on each request
  const serverTimestamp = new Date().toISOString();

  return (
    <main className="container">
      <h1>Server Timestamp</h1>
      <div className="timestamp-card">
        <p>Current server time (UTC):</p>
        <time dateTime={serverTimestamp} className="timestamp">
          {serverTimestamp}
        </time>
        <p className="note">
          This timestamp is generated on the server for each request.
          It will be different every time you refresh the page.
        </p>
      </div>
      <div className="actions">
        <a href="/" className="back-link">← Back to Home</a>
        <button 
          onClick={() => window.location.reload()} 
          className="refresh-btn"
        >
          Refresh Page
        </button>
      </div>

      <style jsx>{`
        .container {
          max-width: 800px;
          margin: 0 auto;
          padding: 2rem;
          font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
        }

        h1 {
          color: #1f2937;
          margin-bottom: 2rem;
          text-align: center;
        }

        .timestamp-card {
          background: #f3f4f6;
          border-radius: 12px;
          padding: 2rem;
          text-align: center;
          border: 1px solid #e5e7eb;
        }

        .timestamp {
          font-size: 1.5rem;
          font-family: 'Courier New', monospace;
          font-weight: bold;
          color: #059669;
          margin: 1rem 0;
          display: block;
        }

        .note {
          color: #6b7280;
          font-size: 0.9rem;
          margin-top: 1rem;
          line-height: 1.5;
        }

        .actions {
          display: flex;
          justify-content: center;
          gap: 1rem;
          margin-top: 2rem;
        }

        .back-link {
          padding: 0.5rem 1rem;
          background: #3b82f6;
          color: white;
          text-decoration: none;
          border-radius: 6px;
          transition: background 0.2s;
        }

        .back-link:hover {
          background: #2563eb;
        }

        .refresh-btn {
          padding: 0.5rem 1rem;
          background: #10b981;
          color: white;
          border: none;
          border-radius: 6px;
          cursor: pointer;
          transition: background 0.2s;
        }

        .refresh-btn:hover {
          background: #059669;
        }
      `}</style>
    </main>
  );
}

