input.newString:
export default function Home() {
  // This is a Server Component (default in App Router)
  // The timestamp and random number will be generated fresh on each request
  const serverTimestamp = new Date().toISOString();
  const randomNumber = Math.floor(Math.random() * 100) + 1;

  return (
    <main>
      <h1>Random Number Generator</h1>
      <div>
        <p>Current server time: <strong>{serverTimestamp}</strong></p>
        <p>Your random number: <strong>{randomNumber}</strong></p>
        <p style={{ fontSize: '0.9rem', color: '#666' }}>
          Both values are generated fresh on the server for each request.
        </p>
      </div>
    </main>
  );
}

